import math

def T(n):
    if n == 1:
        return 1
    return 2 * T(n // 2) + n

for n in [1, 2, 4, 8, 16, 1024]:
    print(f"n = {n:5}:  T(n) = {T(n):6}   n·log2(n) + n = {round(n * math.log2(n) + n):6}")

